    public void testTranslate_PartialMatchAtEnd() throws IOException {
        // Setup: "bc" -> "2"
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"bc", "2"}
        );

        StringWriter writer = new StringWriter();
        String input = "abc";

        // Test index 1: input.length() - index = 2.
